const { Scalekit } = require('@scalekit-sdk/node');
const fs = require('fs');

async function main() {
  const trialId = fs.readFileSync('/logs/trial_id', 'utf8').trim();
  const externalId = 'ext_org_' + trialId;

  const scalekit = new Scalekit(
    process.env.SCALEKIT_ENVIRONMENT_URL,
    process.env.SCALEKIT_CLIENT_ID,
    process.env.SCALEKIT_CLIENT_SECRET
  );

  try {
    const org = await scalekit.organization.createOrganization({
      display_name: 'Harbor Test Org',
      external_id: externalId
    });

    console.log('Created org:', org);

    const orgs = await scalekit.organization.listOrganizations();
    console.log('Listed orgs:', orgs);

    let foundOrg = null;
    // Assuming listOrganizations returns an object with `organizations` or just an array
    const orgList = orgs.organizations || orgs;

    for (const o of orgList) {
      if (o.external_id === externalId || o.externalId === externalId) {
        foundOrg = o;
        break;
      }
    }

    if (foundOrg) {
      fs.writeFileSync('/home/user/scalekit-orgs/org_id.txt', foundOrg.id);
      console.log('Successfully wrote org id to file');
    } else {
      console.error('Organization not found in the list');
    }
  } catch (error) {
    console.error('Error:', error);
  }
}

main();

