const fs = require('fs');

async function main() {
  const trialId = fs.readFileSync('/logs/trial_id', 'utf8').trim();
  const externalId = 'ext_org_' + trialId;

  const scalekit = new Scalekit(
    process.env.SCALEKIT_ENVIRONMENT_URL,
    process.env.SCALEKIT_CLIENT_ID,
    process.env.SCALEKIT_CLIENT_SECRET
  );

  try {
    try {
      // Creates an organization using scalekit.organization.createOrganization() with display_name: 'Harbor Test Org' and external_id: 'ext_org_' + trial_id.
      // Note: The SDK method signature is createOrganization(name, options) where options can contain externalId.
      const orgRes = await scalekit.organization.createOrganization('Harbor Test Org', {
        externalId: externalId
      });
      console.log('Created org:', orgRes);
    } catch (e) {
      if (e.message && e.message.includes('already exists')) {
        console.log('Organization already exists, proceeding to list...');
      } else {
        throw e;
      }
    }

    // Lists organizations using scalekit.organization.listOrganizations().
    // Note: The SDK method is actually named listOrganization() in the current version.
    const orgsRes = await scalekit.organization.listOrganization();
    console.log('Listed orgs:', orgsRes);

    let foundOrg = null;
    const orgList = orgsRes.organizations || [];

    for (const o of orgList) {
      if (o.externalId === externalId || o.external_id === externalId) {
        foundOrg = o;
        break;
      }
    }

    if (foundOrg) {
      fs.writeFileSync('/home/user/scalekit-orgs/org_id.txt', foundOrg.id);
      console.log('Successfully wrote org id to file');
    } else {
      console.error('Organization not found in the list');
    }
  } catch (error) {
    console.error('Error:', error);
  }
}

main();
